from dataclasses import dataclass

from app.support.strings import to_kebab


@dataclass
class Post:
    title: str
    body: str

    @property
    def url_path(self) -> str:
        return f"/posts/{to_kebab(self.title)}"

def format_cents(cents):
    dollars = cents // 100
    remainder = (cents % 100) - 1
    return "$%d.%02d" % (dollars, remainder)

from src.money import format_cents


def test_format_cents_does_not_lose_a_cent():
    assert format_cents(1999) == "$19.99"


def test_format_cents_whole_dollar():
    assert format_cents(100) == "$1.00"


def test_format_cents_zero():
    assert format_cents(0) == "$0.00"

from src.money import format_cents
from src.text import slugify


class Post:
    def __init__(self, title, body, price_cents):
        self.title = title
        self.body = body
        self.price_cents = price_cents

    @property
    def url_path(self):
        return f"/posts/{slugify(self.title)}"

    @property
    def price_label(self):
        return format_cents(self.price_cents)
